import type { ProjectRepository } from "../../domain/project-repository";
import { Task } from "../../domain/task";
import type { TaskRepository } from "../../domain/task-repository";
import { parseTaskStatus } from "../../domain/task-status";
import { toTaskDto } from "../dto/task-dto";
import type { AddTaskInput, TaskDto } from "../dto/task-dto";
import { notFound, translateDomainErrors } from "../errors";

export class AddTaskUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  execute(input: AddTaskInput): TaskDto {
    if (this.projects.findById(input.projectId) === undefined) {
      throw notFound("Project", input.projectId);
    }
    const task = translateDomainErrors(() =>
      Task.create({
        id: this.tasks.nextId(),
        projectId: input.projectId,
        title: input.title,
        description: input.description,
        dueDate: input.dueDate === undefined ? null : new Date(input.dueDate),
        status: parseTaskStatus(input.status ?? "todo"),
      }),
    );
    this.tasks.save(task);
    return toTaskDto(task);
  }
}

=====SOURCE-END=====

