import type { TaskRepository } from "../../domain/task-repository";
import type { UserRepository } from "../../domain/user-repository";
import { toTaskDto } from "../dto/task-dto";
import type { AssignTaskInput, TaskDto } from "../dto/task-dto";
import { notFound } from "../errors";

export class AssignTaskUseCase {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
  ) {}

  execute(input: AssignTaskInput): TaskDto {
    const task = this.tasks.findById(input.taskId);
    if (task === undefined) {
      throw notFound("Task", input.taskId);
    }
    const assignee = this.users.findById(input.assigneeId);
    if (assignee === undefined) {
      throw notFound("User", input.assigneeId);
    }
    task.assignTo(assignee.id);
    this.tasks.save(task);
    return toTaskDto(task);
  }
}

=====SOURCE-END=====

