import type { ProjectRepository } from "../../domain/project-repository";
import type { TaskFilter, TaskRepository } from "../../domain/task-repository";
import { parseTaskStatus } from "../../domain/task-status";
import { toTaskDto } from "../dto/task-dto";
import type { ListProjectTasksInput, TaskDto } from "../dto/task-dto";
import { notFound, translateDomainErrors } from "../errors";

export class ListProjectTasksUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  execute(input: ListProjectTasksInput): TaskDto[] {
    if (this.projects.findById(input.projectId) === undefined) {
      throw notFound("Project", input.projectId);
    }
    const filter: TaskFilter = {};
    if (input.status !== undefined) {
      const status = input.status;
      filter.status = translateDomainErrors(() => parseTaskStatus(status));
    }
    if (input.assigneeId !== undefined) {
      filter.assigneeId = input.assigneeId;
    }
    return this.tasks.findByProject(input.projectId, filter).map(toTaskDto);
  }
}

=====SOURCE-END=====

