import type { TaskRepository } from "../../domain/task-repository";
import { toTaskDto } from "../dto/task-dto";
import type { TaskDto } from "../dto/task-dto";
import { notFound, translateDomainErrors } from "../errors";

export class MarkTaskDoneUseCase {
  constructor(private readonly tasks: TaskRepository) {}

  execute(taskId: string): TaskDto {
    const task = this.tasks.findById(taskId);
    if (task === undefined) {
      throw notFound("Task", taskId);
    }
    translateDomainErrors(() => task.markDone());
    this.tasks.save(task);
    return toTaskDto(task);
  }
}

